-- AIDS Department Official Student Roster Seed Script
-- Idempotent seed: 'ON CONFLICT DO NOTHING' ensures if updated, don't update/overwrite it.

-- 1. Ensure Sections Table is Populated
ON CONFLICT (section_id) DO UPDATE SET total_strength = EXCLUDED.total_strength;

-- 2. Seed Users & Students
ON CONFLICT (email) DO NOTHING;

ON CONFLICT (roll_number) DO NOTHING;
